INSERT INTO operation_log (
    id, user_id, operation, target_type, target_id, 
    operation_time, ip_address, detail
) VALUES (
    #{id}, #{userId}, #{operation}, #{targetType}, #{targetId}, 
    #{operationTime}, #{ipAddress}, #{detail}
)

mapper.select:
SELECT ol.id, ol.user_id, ol.operation, ol.target_type, ol.target_id, ol.operation_time, ol.ip_address, ol.detail, u.id as u_id, u.username as u_username, u.real_name as u_real_name, u.department as u_department FROM operation_log ol LEFT JOIN user u ON ol.user_id = u.id
AND ol.user_id = #{userId}
AND ol.operation = #{operation}
AND ol.operation_time >= #{startTime}
AND ol.operation_time <= #{endTime}
ORDER BY ol.operation_time DESC

SELECT ol.id, ol.user_id, ol.operation, ol.target_type, ol.target_id, ol.operation_time, ol.ip_address, ol.detail, u.id as u_id, u.username as u_username, u.real_name as u_real_name, u.department as u_department FROM operation_log ol LEFT JOIN user u ON ol.user_id = u.id
AND ol.user_id = #{userId}
AND ol.operation = #{operation}
AND ol.operation = #{operationType}
AND u.username = #{username}
AND ol.detail LIKE CONCAT('%', #{status}, '%')
AND ol.target_type = #{targetType}
AND ol.target_id = #{targetId}
AND ol.target_id = #{knowledgeBaseId} AND ol.target_type = 'knowledge_base'
AND (ol.operation LIKE CONCAT('%', #{query}, '%') OR ol.target_type LIKE CONCAT('%', #{query}, '%') OR u.username LIKE CONCAT('%', #{query}, '%') OR u.real_name LIKE CONCAT('%', #{query}, '%'))
AND ol.operation_time >= #{startTime}
AND ol.operation_time <= #{endTime}
ORDER BY ol.operation_time DESC

